import { describe, expect, test } from 'vitest';
import { linesWithIgnoreWithoutReason } from '../src/index.js';

describe('a jscpd:ignore-start needs a reason on the same line', () => {
  test.each([
    '// jscpd:ignore-start — generated by the OpenAPI client',
    '// jscpd:ignore-start -- the two adapters must stay independent',
    '// jscpd:ignore-start: copied from the vendor SDK, see LICENSE',
    '/* jscpd:ignore-start — table of test cases */',
    '<!-- jscpd:ignore-start — Spartan template -->',
    '# jscpd:ignore-start -- migration snapshot',
  ])('%s has a reason', (line) => {
    expect(linesWithIgnoreWithoutReason(line)).toEqual([]);
  });

  test.each([
    '// jscpd:ignore-start',
    '// jscpd:ignore-start   ',
    '// jscpd:ignore-start —',
    '/* jscpd:ignore-start */',
    '<!-- jscpd:ignore-start -->',
    '// jscpd:ignore-start because I said so',
  ])('%s has no reason', (line) => {
    expect(linesWithIgnoreWithoutReason(line)).toEqual([1]);
  });

  test('reports the 1-based line of each unexplained ignore', () => {
    const source = [
      'const first = 1;',
      '// jscpd:ignore-start',
      'const copy = 1;',
      '// jscpd:ignore-end',
      '// jscpd:ignore-start — fixture table',
      '// jscpd:ignore-end',
    ].join('\n');
    expect(linesWithIgnoreWithoutReason(source)).toEqual([2]);
  });
});
